      out.write("    // Countdown timers\r\n");
      out.write("    function pad(n) { return String(n).padStart(2, \"0\"); }\r\n");
      out.write("\r\n");
      out.write("    function formatRemaining(ms) {\r\n");
      out.write("        if (ms <= 0) return null;\r\n");
      out.write("        const s = Math.floor(ms / 1000);\r\n");
