      out.write("                const box = el.closest(\".countdown-box\");\r\n");
      out.write("                if (box) {\r\n");
      out.write("                    const d = document.createElement(\"div\");\r\n");
      out.write("                    d.className = \"countdown-ended\";\r\n");
      out.write("                    d.textContent = \"Ended: \" + endFmt;\r\n");
      out.write("                    box.replaceWith(d);\r\n");
      out.write("                }\r\n");
      out.write("                const card = el.closest(\".item-card\");\r\n");
      out.write("                if (card) {\r\n");
      out.write("                    card.classList.add(\"ended\");\r\n");
      out.write("                    card.dataset.status = \"closed\";\r\n");
      out.write("                    const btn = card.querySelector(\".bid-btn\");\r\n");
      out.write("                    if (btn) {\r\n");
      out.write("                        const dis = document.createElement(\"button\");\r\n");
      out.write("                        dis.className = \"bid-btn-ended\";\r\n");
      out.write("                        dis.textContent = \"Auction Closed\";\r\n");
      out.write("                        dis.disabled = true;\r\n");
      out.write("                        btn.replaceWith(dis);\r\n");
      out.write("                    }\r\n");
      out.write("                    const sb = card.querySelector(\".status-badge\");\r\n");
      out.write("                    if (sb) { sb.className = \"status-badge badge-ended\"; sb.textContent = \"Closed\"; }\r\n");
      out.write("                }\r\n");
      out.write("            } else {\r\n");
      out.write("                el.textContent = formatRemaining(rem);\r\n");
      out.write("                el.classList.toggle(\"urgent\", rem < 3600000);\r\n");
      out.write("            }\r\n");
      out.write("        });\r\n");
      out.write("    }\r\n");
      out.write("\r\n");
      out.write("    tickCountdowns();\r\n");
      out.write("    setInterval(tickCountdowns, 1000);\r\n");
      out.write("</script>\r\n");
